cases.good:
// 1. Chỉ chạy ở top frame; bỏ qua Cloudflare challenge iframe
if (window.self !== window.top) return;

// 2. Đợi load + DOM quiescence trước khi scan/mutate
function activateAfterStability(): void {
  let stabilityTimer: ReturnType<typeof setTimeout> | null = null;
  const observer = new MutationObserver(() => scheduleStabilityCheck());
  const scheduleStabilityCheck = (): void => {
    if (stabilityTimer) clearTimeout(stabilityTimer);
    stabilityTimer = setTimeout(() => {
      observer.disconnect();
      if (state.enabled) setActive(true);
    }, 500);
  };
  observer.observe(document.documentElement, { childList: true, subtree: true });
  scheduleStabilityCheck();
}
if (document.readyState === 'complete') activateAfterStability();
else window.addEventListener('load', activateAfterStability, { once: true });
